add_filter( 'woocommerce_form_field', 'perfectpixel_inline_required_error', 10, 4 );
add_action( 'wp_head', 'perfectpixel_inline_required_error_css' );

function perfectpixel_inline_required_error( $field, $key, $args, $value ) {
	if ( empty( $args['required'] ) || empty( $args['label'] ) || ! function_exists( 'is_checkout' ) || ! is_checkout() ) {
		return $field;
	}
	$message = sprintf( __( '%s is a required field.', 'woocommerce' ), wp_strip_all_tags( $args['label'] ) );
	$error   = '<span class="perfectpixel-inline-error" role="alert">' . esc_html( $message ) . '</span>';

	// Insert just before the closing tag of the field row.
	$pos = strrpos( $field, '</p>' );
	return false === $pos ? $field . $error : substr_replace( $field, $error . '</p>', $pos, 4 );
}

function perfectpixel_inline_required_error_css() {
	if ( ! function_exists( 'is_checkout' ) || ! is_checkout() ) {
		return;
	}
	echo '<style>.perfectpixel-inline-error{display:none;color:#b81c23;font-size:.875em;margin-top:.25em}.woocommerce-invalid-required-field .perfectpixel-inline-error{display:block}</style>';
}
